/**
 * Detects changes using normalized code, then generates a diff
 * including a summary and the full text of both definitions.
 */
const diff = require('diff');
const outputItems = [];

for (const item of $input.all()) {
    const data = item.json;

    const normalizedCode1 = data.dev_NORMALIZED_CODE;
    const normalizedCode2 = data.prod_NORMALIZED_CODE;
    const definition1 = data.dev_DEFINITION; // Development code
    const definition2 = data.prod_DEFINITION; // Production code

    const name1 = (data.dev_SCHEMA_NAME || 'dev') + '.' + (data.dev_ROUTINE_NAME || 'unknown');

    let hasChanges = false;
    let changeType = '';
    let conciseDiffOutput = '';

    // Case 1: Procedure exists in both environments
    if (normalizedCode1 && normalizedCode2) {
        if (normalizedCode1 !== normalizedCode2) {
            hasChanges = true;
            changeType = 'MODIFIED';

            const changes = diff.diffLines(definition2 || '', definition1 || '');
            let devLineNum = 1, prodLineNum = 1;
            const devLinesAdded = [], prodLinesRemoved = [];

            changes.forEach(part => {
                const numLines = part.count || 0;
                if (part.added) {
                    part.value.trimEnd().split('\n').forEach(line => {
                        devLinesAdded.push(`+ L${devLineNum}: ${line}`);
                        devLineNum++;
                    });
                } else if (part.removed) {
                    part.value.trimEnd().split('\n').forEach(line => {
                        prodLinesRemoved.push(`- L${prodLineNum}: ${line}`);
                        prodLineNum++;
                    });
                } else {
                    devLineNum += numLines;
                    prodLineNum += numLines;
                }
            });

            let output = `Changes for ${name1}:\n`;
            if (devLinesAdded.length > 0) {
                output += `\n+++ Development Code (Added) +++\n${devLinesAdded.join('\n')}`;
            }
            if (prodLinesRemoved.length > 0) {
                output += `\n\n--- Production Code (Removed) ---\n${prodLinesRemoved.join('\n')}`;
            }

            // --- MODIFICATION START ---
            // Store the diff-only summary
            const diffSummary = output; 

            // Build the new comprehensive output
            conciseDiffOutput = `
--- CHANGE SUMMARY ---
${diffSummary}

--- FULL DEVELOPMENT CODE ---
${definition1 || '(No code in development)'}

--- FULL PRODUCTION CODE ---
${definition2 || '(No code in production)'}
`;
            // --- MODIFICATION END ---
        }
    } 
    // Case 2: Procedure is missing from one environment
    else {
        if (normalizedCode1 && !normalizedCode2) {
            hasChanges = true;
            changeType = 'NEW';

            // --- MODIFICATION START ---
            conciseDiffOutput = `
--- CHANGE SUMMARY ---
This procedure is new and exists only in the Development environment.

--- FULL DEVELOPMENT CODE ---
${definition1 || 'N/A'}

--- FULL PRODUCTION CODE ---
(No code in production)
`;
            // --- MODIFICATION END ---
        } 
        else if (!normalizedCode1 && normalizedCode2) {
            hasChanges = true;
            changeType = 'DELETED';

            // --- MODIFICATION START ---
            conciseDiffOutput = `
--- CHANGE SUMMARY ---
This procedure exists in Production but has been removed from the Development environment.

--- FULL DEVELOPMENT CODE ---
(No code in development)

--- FULL PRODUCTION CODE ---
${definition2 || 'N/A'}
`;
            // --- MODIFICATION END ---
        }
    }

    // Only add item to the output if a change was detected
    if (hasChanges) {
        const outputData = {
            procedure_name: (data.dev_SCHEMA_NAME || data.prod_SCHEMA_NAME || 'dbo') + '.' + (data.dev_ROUTINE_NAME || data.prod_ROUTINE_NAME),
            change_type: changeType,
            changes_only: conciseDiffOutput,
            // Pass the original dev definition for the 'approve' logic
            dev_DEFINITION: definition1 
        };
        outputItems.push({ json: outputData });
    }
}
return outputItems;

/**
 * Normalizes and prefixes fields for an environment.
 */
const outputItems = [];

for (const item of $input.all()) {
    const procedure = item.json;
    let text = procedure.DEFINITION || '';

    // --- Normalization Logic ---
    text = text.replace(/\/\**?\*\//g, '');      // Remove multi-line comments
    text = text.replace(/--.*$/gm, '');          // Remove single-line comments
    text = text.replace(/^\s*GO\s*$/gmi, '');    // Remove GO statements
    text = text.replace(/(\r\n|\r)/g, '\n');     // Standardize line endings
    text = text.replace(/[ \t]{2,}/g, ' ');      // Normalize spacing
    text = text.replace(/^[ \t]+|[ \t]+$/gm, ''); // Trim each line
    text = text.replace(/(\n){2,}/g, '\n');      // Remove empty lines
    text = text.trim();                          // Final trim

    // **NEW STEP:** Convert everything to lowercase to ignore case differences.
    text = text.toLowerCase();

    // --- The rest of your specific dev/prod prefixing logic remains the same ---
    // (This example is for the 'normalize 1' (dev) node)
    const devData = {
      dev_ROUTINE_NAME: procedure.ROUTINE_NAME,
      dev_SCHEMA_NAME: procedure.SCHEMA_NAME,
      dev_DEFINITION: procedure.DEFINITION,
      dev_NORMALIZED_CODE: text
    };

    outputItems.push({ json: devData });
}

return outputItems;

/**
 * Normalizes and prefixes fields for the PRODUCTION environment.
 */
const outputItems = [];

for (const item of $input.all()) {
    const procedure = item.json;
    let text = procedure.DEFINITION || '';

    // --- Your normalization logic (regex replaces) stays the same ---
    text = text.replace(/\/\**?\*\//g, '');      // Remove multi-line comments
    text = text.replace(/--.*$/gm, '');          // Remove single-line comments
    text = text.replace(/^\s*GO\s*$/gmi, '');    // Remove GO statements
    text = text.replace(/(\r\n|\r)/g, '\n');     // Standardize line endings
    text = text.replace(/[ \t]{2,}/g, ' ');      // Normalize spacing
    text = text.replace(/^[ \t]+|[ \t]+$/gm, ''); // Trim each line
    text = text.replace(/(\n){2,}/g, '\n');      // Remove empty lines
    text = text.trim();                          // Final trim
    // -------------------------------------------------------------
text = text.toLowerCase();
    // Create a new clean object with prefixed names
    const prodData = {
      prod_ROUTINE_NAME: procedure.ROUTINE_NAME,
      prod_SCHEMA_NAME: procedure.SCHEMA_NAME,
      prod_DEFINITION: procedure.DEFINITION,
      prod_NORMALIZED_CODE: text
    };

    outputItems.push({ json: prodData });
}

return outputItems;

const out = {};

for (const item of $input.all()) {
  const key = item.json.config_key;
  const value = item.json.config_value;

  if (key === 'selected_prod_server_name') out.prod_server = value;
  if (key === 'selected_prod_database_name') out.prod_database = value;
  if (key === 'selected_dev_server_name') out.dev_server = value;
  if (key === 'selected_dev_database_name') out.dev_database = value;
}

return [{ json: out }];

// 1. Get the Configuration (Server & DB) from the "normalizze" node
const configItems = $items("normalizze");

if (!configItems.length) {
   throw new Error("Could not find configuration data from 'normalizze' node.");
}

const targetServer = configItems[0].json.prod_server;
const targetDatabase = configItems[0].json.prod_database;

// 2. Get the list of credentials from the CURRENT input (Merge2)
// *** FIX: We access the 'rows' array seen in your screenshot ***
const inputItem = $input.first();
const credentialsList = inputItem.json.rows;

if (!credentialsList || !Array.isArray(credentialsList)) {
  throw new Error("Could not find 'rows' array in input. Check the Merge2 node output.");
}

// Helper function to clean text (removes spaces and handles case sensitivity)
const normalize = (str) => String(str || '').trim().toLowerCase();
const targetNorm = normalize(targetServer);

// 3. Find the matching server inside the rows list
const match = credentialsList.find(row => 
  normalize(row.ServerName) === targetNorm
);

if (!match) {
  // If not found, list available servers in the error message for debugging
  const available = credentialsList.map(r => r.ServerName).join(', ');
  throw new Error(`Server '${targetServer}' not found in credentials. Available: ${available}`);
}

// 4. Output the Clean Credentials + Database
return [{
  json: {
    host: match.ServerName,
    port: parseInt(match.Port || 1433, 10),
    user: String(match.UserName).trim(),
    password: String(match.Password).trim(),
    database: targetDatabase
  }
}];

const sql = require('mssql');
const cfg = $input.first().json;

const config = {
  user: cfg.user,
  password: cfg.password,
  server: cfg.server,
  port: cfg.port,
  database: cfg.database,
  options: {
    encrypt: false,
    trustServerCertificate: true
  }
};

let pool;
try {
  pool = await sql.connect(config);

  const result = await pool.request().query(`
    SELECT
        sch.name AS schema_name,
        p.name AS routine_name,
        mod.definition AS definition
    FROM sys.procedures AS p
    INNER JOIN sys.sql_modules AS mod
        ON mod.object_id = p.object_id
    INNER JOIN sys.schemas AS sch
        ON sch.schema_id = p.schema_id
    WHERE p.is_ms_shipped = 0
    ORDER BY sch.name, p.name;
  `);

  await pool.close();

  return [{
    json: {
      server: cfg.server,
      database: cfg.database,
      procedures: result.recordset
    }
  }];

} catch (err) {
  if (pool) await pool.close();
  throw err;
}

// Function node: merge all incoming sheet items into single item
// Output: [{ json: { rows: [ ... ] } }]
const incoming = $items();

// If incoming is already a single item with rows, just pass it through
if (incoming.length === 1 && incoming[0].json && Array.isArray(incoming[0].json.rows)) {
  return incoming;
}

// Otherwise, collect all .json payloads into rows
const rows = incoming.map(it => it.json || {});
return [{ json: { rows } }];
